CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS admins(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(120) NOT NULL,email VARCHAR(255) UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS customers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),full_name VARCHAR(120) NOT NULL,phone VARCHAR(20) UNIQUE NOT NULL,email VARCHAR(255),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS products(id BIGSERIAL PRIMARY KEY,name VARCHAR(180) UNIQUE NOT NULL,description TEXT,category VARCHAR(80) NOT NULL,price NUMERIC(12,2) NOT NULL CHECK(price>=0),unit VARCHAR(40) NOT NULL,emoji VARCHAR(12) DEFAULT '🛒',badge VARCHAR(50),image_url TEXT,stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS products_category_idx ON products(category);
CREATE TABLE IF NOT EXISTS orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_number BIGSERIAL UNIQUE,customer_id UUID REFERENCES customers(id),customer_name VARCHAR(120) NOT NULL,phone VARCHAR(20) NOT NULL,address TEXT NOT NULL,district VARCHAR(80) NOT NULL,delivery_note TEXT,subtotal NUMERIC(12,2) NOT NULL,delivery_fee NUMERIC(12,2) NOT NULL,total NUMERIC(12,2) NOT NULL,payment_method VARCHAR(20) NOT NULL CHECK(payment_method IN('cod','bkash','nagad','rocket','card')),payment_status VARCHAR(20) NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN('unpaid','pending','paid','failed','refunded')),order_status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(order_status IN('pending','confirmed','processing','shipped','delivered','cancelled')),created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS orders_created_idx ON orders(created_at DESC);
CREATE TABLE IF NOT EXISTS order_items(id BIGSERIAL PRIMARY KEY,order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id BIGINT REFERENCES products(id),product_name VARCHAR(180) NOT NULL,unit VARCHAR(40) NOT NULL,unit_price NUMERIC(12,2) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 99),line_total NUMERIC(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_id UUID NOT NULL REFERENCES orders(id),provider VARCHAR(40) NOT NULL,method VARCHAR(20) NOT NULL,transaction_id VARCHAR(120),provider_session_id VARCHAR(160),amount NUMERIC(12,2) NOT NULL,currency VARCHAR(3) DEFAULT 'BDT',status VARCHAR(20) DEFAULT 'initiated',raw_response JSONB,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS inventory_movements(id BIGSERIAL PRIMARY KEY,product_id BIGINT NOT NULL REFERENCES products(id),order_id UUID REFERENCES orders(id),admin_id UUID REFERENCES admins(id),change_qty INTEGER NOT NULL,reason VARCHAR(180) NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS subscribers(id BIGSERIAL PRIMARY KEY,email VARCHAR(255) UNIQUE NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS http_sessions(sid VARCHAR NOT NULL PRIMARY KEY,sess JSON NOT NULL,expire TIMESTAMP(6) NOT NULL);
CREATE INDEX IF NOT EXISTS http_sessions_expire_idx ON http_sessions(expire);
